-- in psql
LISTEN {{channel_name}};

-- in another session
NOTIFY {{channel_name}}, 'payload-data';

-- trigger to auto-notify on row change
CREATE OR REPLACE FUNCTION notify_change() RETURNS trigger AS $$
BEGIN
  PERFORM pg_notify('{{channel_name}}', row_to_json(NEW)::text);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
